import { useState } from "react";

export default function App() {
  return (
    // group related state
    // avoid contradictions?
    <>
      wow
    </>
  );
}



function AvoidDuplication() {
  const [items, setItems] = useState([
    { food: "hmm, hamburger", id: 0 },
    { food: "apple", id: 1 },
    { food: "pizza!!", id: 2 },
  ]);

  //   const [selectedItem, setSelectedItem] = useState(items[0]) X
  const [selectedId, setSelectedId] = useState(0);
  const selectedItem = items.find((item) => item.id === selectedId); // O

  function handleOnChange(e, id) {
    setItems(
      items.map((item) => {
        if (item.id === id) {
          return { ...item, food: e.target.value };
        } else {
          return item;
        }
      })
    );
  }
  return (
    <>
      {items.map((item) => (
        <list style={{ display: "block" }}>
          <input
            value={item.food}
            onChange={(e) => {
              handleOnChange(e, item.id);
            }}
          />{" "}
          <button
            onClick={() => {
              setSelectedId(item.id);
            }}
          >
            pick
          </button>
        </list>
      ))}
      <p>you pick {items[selectedId].food}</p>
    </>
  );
}

initialList = {
    root: {upperParent: [1,2]},
    1: { list: "1", child: ["a"] },
    a: { subList: ["a1","a2","a3"] },
    "a1": { no: "a1" },
    "a2": { no: "a2" },
    "a3": { no: "a3" },
    2: { list: "2", child: ["b", "c", "d"] },
    "b": { no: "b" },
    "c": { no: "c" },
    "d": { no: "d" },}
    // a = {1: "wow", b: "wow", "1": "wow"}
    // console.log(a.b); console.log(a[1]); console.log(a["1"])
function AvoidDeeplyNested() {
  const [list, setList] = useState({
    root: {upperParent: [1,2]},
    1: { list: "1", child: ["a"] },
    a: { subList: ["a1","a2","a3"] },
    "a1": { no: "a1" },
    "a2": { no: "a2" },
    "a3": { no: "a3" },
    2: { list: "2", child: ["b", "c", "d"] },
    "b": { no: "b" },
    "c": { no: "c" },
    "d": { no: "d" },
  });

  
  return (
    <>
      d
    </>
  );
}
